/**
 * KIT-0 H6: maps a client's theme custom properties (`--client-*`, generated by tools/client-kit from theme/tokens.json) onto the
 * custom properties the agency-core design system and blocks read (`--color-*`, `--s-*`, `--fs-*` ...). The spacing, type and layout
 * scales below are provisional ICST/DD defaults (8 px base, 1172 px content, 79 px header, recommended type scale); a client whose
 * design file says otherwise overrides them in its own `theme/overrides.css`.
 */
export const DS_BRIDGE_CSS = `:root {
  --color-canvas: var(--client-surface);
  --color-surface: var(--client-surface);
  --color-surface-raised: var(--client-surface-alt);
  --color-surface-well: var(--client-surface-alt);
  --color-text-primary: var(--client-text);
  --color-text-body: var(--client-text);
  --color-text-muted: var(--client-text-muted);
  --color-accent: var(--client-accent);
  --color-accent-light: color-mix(in srgb, var(--client-accent) 12%, var(--client-surface));
  --color-accent-dark: var(--client-accent-deep);
  --color-accent-contrast: var(--client-accent-on);
  --color-border: var(--client-rule);
  --color-border-soft: var(--client-rule);
  --color-control-border: var(--client-text-muted);
  --color-success: var(--client-success);
  --color-error: var(--client-error);
  --font-text: var(--client-font-body);
  --font-display: var(--client-font-display);
  --radius: var(--client-radius-card);
  --focus-outline: var(--client-focus-width, 2px) solid var(--client-focus-ring, var(--client-accent));
  --focus-offset: var(--client-focus-offset, 2px);
  --s-1: 4px; --s-2: 8px; --s-3: 12px; --s-4: 16px; --s-5: 24px; --s-6: 32px; --s-7: 48px; --s-8: 64px;
  --fs-n1: 13px; --fs-cap: 12px; --fs-label: 12px; --fs-sm: 14px; --fs-body: 16px; --fs-lead: 20px; --fs-h4: 20px; --fs-h3: 24px;
  --fs-d3: 30px; --fs-d2: 42px; --fs-d1: 62px;
  --w-reg: 400; --w-med: 500; --w-semi: 600; --w-heading: 600;
  --lh-base: 1.5; --lh-lead: 1.5; --lh-snug: 1.3; --lh-tight: 1.15; --lh-d3: 1.15; --lh-d2: 1.1; --lh-d1: 1.05;
  --ls-label: 0.08em; --ls-display: 0;
  --maxw: 1172px; --measure: 68ch; --nav-h: 79px; --z-rail: 10;
  --dur: 160ms; --ease: cubic-bezier(0.2, 0.6, 0.2, 1); --border-hair: 1px;
}
`
